	'kcd9682fd' => 'Out of hours, contract clients: +31 10 555 0149',
	'kce0be71e' => 'Log',
	'kce905686' => 'Mid-season coil and drain clean, plus readings.',
	'kcf57b687' => 'Twelve visits a year for larger buildings that need continuous oversight and a full mechanical log.',
